 static List<Shape> load(){List<Shape> out=new ArrayList<>();try(var in=Remains48.class.getResourceAsStream("remains48.txt")){if(in==null)throw new IOException("Missing remains footprints");for(String s:new String(in.readAllBytes(),StandardCharsets.UTF_8).split("\n")){if(s.isBlank())continue;String[] v=s.split(" ");String[] cells=v[4].split(";");int[][] c=new int[cells.length][];for(int i=0;i<c.length;i++)c[i]=Arrays.stream(cells[i].split(",")).mapToInt(Integer::parseInt).toArray();out.add(new Shape(v[0],Integer.parseInt(v[1]),Double.parseDouble(v[2]),Double.parseDouble(v[3]),c));}}catch(IOException e){throw new ExceptionInInitializerError(e);}return List.copyOf(out);}
